import React, { useState } from 'react';
import Hero from './components/Hero';
import AboutPage from './components/AboutPage';
import WallOfRunes from './components/WallOfRunes';

function App() {
  const [currentPage, setCurrentPage] = useState('hero');

  const handlePageChange = (page) => {
    setCurrentPage(page);
  };

  const handleGameComplete = () => {
    setCurrentPage('about');
  };

  return (
    <div className="bg-gray-900 font-sans text-white">
      {currentPage === 'hero' && <Hero onButtonClick={() => handlePageChange('about')} />}
      {currentPage === 'about' && <AboutPage onGameStart={(game) => setCurrentPage(game)} />}
      {currentPage === 'wall-of-runes' && <WallOfRunes onGameComplete={handleGameComplete} />}
    </div>
  );
}

export default App;
